css:
@page { size: 90mm 130mm; margin: 0; }
body { margin: 0; }
.ido-badge { width: 90mm; height: 130mm; position: relative; box-sizing: border-box;
  font-family: "Tahoma", "Arial", sans-serif; text-align: center; overflow: hidden;
  background: #fff; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.ido-badge .bg-top { position: absolute; top: 0; left: 0; right: 0; height: 34mm;
  background: linear-gradient(140deg, #25255a, #5c2d91 55%, #7f529e);
  border-radius: 0 0 42% 42% / 0 0 18% 18%; }
.ido-badge .head { position: relative; padding-top: 7mm; color: #fff; }
.ido-badge .brand { font-size: 15pt; font-weight: 800; letter-spacing: -.4pt; }
.ido-badge .brand span { display: block; font-size: 6pt; font-weight: 500; letter-spacing: 2.4pt; opacity: .85; }
.ido-badge .ev { font-size: 7pt; opacity: .9; margin-top: 1.5mm; }
.ido-badge .photo { position: relative; width: 30mm; height: 30mm; margin: 4mm auto 0;
  border-radius: 50%; overflow: hidden; border: 1.2mm solid #fff; background: #efe8f8;
  box-shadow: 0 2mm 5mm rgba(55,27,87,.25); }
.ido-badge .photo img { width: 100%; height: 100%; object-fit: cover; display: block; }
.ido-badge .photo .ph { line-height: 27mm; font-size: 26pt; font-weight: 800; color: #7f529e; }
.ido-badge .name { margin-top: 4mm; font-size: 14pt; font-weight: 800; color: #231f20; padding: 0 5mm; line-height: 1.25; }
.ido-badge .role { font-size: 8.5pt; color: #5c2d91; margin-top: 1mm; padding: 0 6mm; }
.ido-badge .org { font-size: 8pt; color: #666; margin-top: .8mm; padding: 0 6mm; }
.ido-badge .type { display: inline-block; margin-top: 3mm; padding: 1.4mm 6mm; border-radius: 9mm;
  font-size: 8pt; font-weight: 800; letter-spacing: .6pt; background: #efe8f8; color: #45226d; }
.ido-badge .type-vip { background: #fbf0da; color: #8a5a00; }
.ido-badge .type-speaker { background: #e3f5ec; color: #1f6b45; }
.ido-badge .type-media { background: #e6eefb; color: #1f4d8a; }
.ido-badge .type-sponsor { background: #fbe3e3; color: #8a2b2b; }
.ido-badge .qr { position: absolute; bottom: 11mm; left: 0; right: 0; }
.ido-badge .qr img { width: 24mm; height: 24mm; }
.ido-badge .serial { font-size: 7pt; color: #888; margin-top: 1mm; letter-spacing: .6pt; }
.ido-badge .serial.noqr { margin-top: 12mm; font-size: 8pt; }
.ido-badge .foot { position: absolute; bottom: 4mm; left: 0; right: 0; font-size: 6.5pt; color: #aaa; }
